def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for x in my if x == 'D')

    last_op = op[-1]
    last_my = my[-1]
    remaining = 100 - n

    # Opponent quase sempre coopera: coopere e explore no fim
    if opp_d == 0:
        if remaining <= 3:
            return 'D'
        if n >= 50 and (n % 17 == 0):
            return 'D'
        return 'C'

    # Opponent quase sempre defeta: defeite
    if opp_c <= 1 and n >= 8:
        return 'D'

    # Detectar oponente agressivo
    if opp_d * 5 >= n * 3:
        if remaining <= 2:
            return 'D'
        if last_op == 'D':
            return 'D'
        if n % 7 == 0:
            return 'C'
        return 'D'

    # Oponente moderado/cooperativo
    if last_op == 'C':
        if last_my == 'D':
            return 'C'
        # explorar contra muito cooperativo
        if opp_d == 1 and n >= 30 and remaining > 10:
            return 'C'
        return 'C'

    # last_op == 'D'
    if n >= 3:
        # verificar se e isolado
        recent_d = 0
        for i in range(n - 1, max(-1, n - 5), -1):
            if op[i] == 'D':
                recent_d += 1
            else:
                break
        if recent_d == 1 and opp_d * 3 <= n:
            # retaliar uma vez mas continuar
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        if recent_d >= 2:
            return 'D'
    # perdao ocasional
    if rng.random() < 0.1:
        return 'C'
    return 'D'
